"""Giải thích trực quan các phép vector và ma trận xuyên suốt phần A."""

MATRIX_NOTES = {
 (2,0): '''<div class="concept"><strong>Phép nhân tạo ra gì?</strong> a·b là <em>một số</em>: phần của b cùng hướng a, nhân với độ lớn a. Vì thế F·s chỉ đếm phần lực thực sự góp vào chuyển động. a×b là <em>một vector</em> vuông góc mặt phẳng chứa a,b; độ lớn đo tác dụng gây quay. Với r×F, vector kết quả chỉ trục và chiều mô-men. Khi r hoặc F bằng 0, hoặc hai vector song song, không có mô-men.</div>''',
 (2,1): '''<div class="concept"><strong>Ma trận nhân vector làm gì?</strong> Với y=Av, mỗi cột của A là ảnh của một trục cơ sở: Av=v₁cột₁+v₂cột₂+… . Ta dùng một bảng hệ số để áp cùng một phép biến đổi lên mọi vector, thay vì viết lại từng tọa độ. Ma trận xoay đổi tọa độ giữa hai hệ trục; ma trận mixer đổi bốn lực rotor thành tổng lực và ba mô-men. Chỉ ma trận vuông đủ hạng mới có nghịch đảo duy nhất; mixer mất hạng khi mất một hướng điều khiển độc lập.</div><div class="formula">R<sub>z</sub>(90°) [1,0,0]ᵀ = [0,1,0]ᵀ: trục x ban đầu xuất hiện trên trục y sau khi xoay 90°.</div>''',
 (2,2): '''<div class="concept"><strong>Thứ tự là chuyển động khác:</strong> với e<sub>z</sub>=(0,0,1), R<sub>z</sub>(90°)R<sub>x</sub>(90°)e<sub>z</sub>=(1,0,0), nhưng R<sub>x</sub>(90°)R<sub>z</sub>(90°)e<sub>z</sub>=(0,−1,0). Phép ở sát vector được làm trước. RᵀR=I giữ độ dài/góc; det(R)=+1 giữ cả chiều tay phải. Phản xạ qua gương như diag(−1,1,1) có det=−1 nên không phải tư thế quay của drone.</div><div class="concept"><strong>Vì sao viết [a]×?</strong> Khi a đã biết, phép b ↦ a×b là một biến đổi tuyến tính của b, nên viết thành ma trận để dùng chung trong phương trình. Với r=(0,20;0;0) và F=(0;0;5), [r]×F=(0;−1;0) N·m đúng như cách tính tích có hướng. A5 dùng cùng dạng ma trận để viết tốc độ quay của R.</div>''',
 (3,0): '''<div class="concept"><strong>Jacobian là ma trận nhạy cảm:</strong> mỗi cột cho biết một thay đổi nhỏ của một biến đầu vào lan sang tất cả đầu ra thế nào. Trong δẋ=Aδx+Bδu, cột của A là ảnh hưởng của một trạng thái, cột của B là ảnh hưởng của một lệnh. Nhờ gom thành ma trận, ta có thể tính và kiểm tra đồng thời các ghép trục gần hover; đây chỉ là xấp xỉ tại điểm đang xét.</div>''',
 (4,0): '''<div class="concept"><strong>Vì sao phải nhân R?</strong> Hai bộ số có thể mô tả cùng một mũi tên vật lý nhưng dựa trên trục khác nhau. Nếu drone yaw +90° quanh z, vector “tiến 1 m” trong body là (1,0,0) nhưng trong world là (0,1,0). R biến tọa độ body thành world; Rᵀ làm chiều ngược lại vì R là ma trận xoay.</div>''',
 (4,1): '''<div class="concept">Ba cột của R lần lượt là hướng trục mũi, trục trái và trục lên của drone nhìn từ world. Nhân R với (1,0,0) chỉ lấy cột thứ nhất; nhân với (0,0,T) lấy cột thứ ba rồi nhân T. Điều này giải thích vì sao drone nghiêng thì lực đẩy xuất hiện thành phần ngang trong world.</div>''',
 (4,2): '''<div class="concept"><strong>Quaternion và ma trận làm việc cùng nhau:</strong> q là cách lưu và tích phân tư thế gọn, còn R(q) là cách lấy ba trục thân trong world để đổi vector lực, vận tốc hoặc cảm biến. Chúng biểu diễn cùng một hướng; chọn dạng theo phép tính đang làm, không cộng tọa độ body với world chỉ vì đã có q.</div>''',
 (5,0): '''<div class="concept"><strong>Trong động học:</strong> vᵇ=(1,0,0) m/s luôn nghĩa là bay về phía mũi. Khi drone đổi yaw, hướng mũi trong world đổi, nên ṙʷ=Rvᵇ cũng đổi dù ba số vᵇ giữ nguyên. Cộng trực tiếp vᵇ vào rʷ sẽ làm quỹ đạo bay sai hướng.</div>''',
 (5,1): '''<div class="concept"><strong>Ma trận W đổi loại tốc độ góc:</strong> [φ̇,θ̇,ψ̇] là tốc độ thay đổi ba tham số Euler; [p,q,r] là tốc độ quay vật lý quanh các trục thân tức thời. W phụ thuộc tư thế và ghép các thành phần này. Gần pitch ±90°, W mất khả năng tách riêng các tốc độ Euler, dù gyro vẫn đo p,q,r bình thường; đó là lý do tích phân quaternion được ưu tiên trong estimator.</div>''',
 (7,1): '''<div class="concept"><strong>Vì sao quán tính là ma trận?</strong> Mô-men động lượng L không nhất thiết cùng hướng với tốc độ quay ω khi khối lượng lệch trục. Jω cộng ảnh hưởng của cả ba thành phần ω; các phần tử ngoài đường chéo thể hiện ghép trục. Trên trục chính, J trở thành dạng chéo nên mỗi trục có một moment quán tính riêng, dễ hình dung và tính hơn.</div>''',
 (10,2): '''<div class="concept"><strong>Đọc từng cột của mixer:</strong> trong u=Mf với f là bốn thrust, cột i nói riêng motor i đóng góp bao nhiêu vào [T,τx,τy,τz]. Cộng bốn cột đã nhân thrust sẽ ra tác động tổng. Chiều quay rotor quyết định dấu hàng yaw; vị trí rotor quyết định dấu hàng roll/pitch. Đảo dây, đổi thứ tự motor hoặc đổi chiều quay mà giữ ma trận cũ sẽ cho lệnh sai.</div>''',
 (13,1): '''<div class="concept"><strong>Ma trận trong phương trình bay:</strong> lực đẩy là (0,0,T) trong body, nhưng gia tốc vị trí được tính trong world. R(0,0,T) đổi lực sang world trước khi cộng trọng lực và lực cản. Ma trận J đổi tốc độ góc thành mô-men động lượng trong body; hai ma trận phục vụ hai phép biến đổi vật lý khác nhau.</div>''',
 (14,0): '''<div class="concept"><strong>A và B tác dụng gì?</strong> Với δẋ=Aδx+Bδu, A cho thấy sai lệch trạng thái hiện tại tự lan truyền/ghép trục ra sao; B cho thấy mỗi lệnh lực hoặc mô-men thay đổi đạo hàm trạng thái nào. Ví dụ gần hover, cột pitch của A làm xuất hiện gia tốc x≈gθ. Các ma trận không phải hình dạng drone: chúng là bản đồ các tác động nhỏ quanh một điểm bay.</div>''',
 (14,2): '''<div class="concept"><strong>Hạng kiểm tra khả năng tác động/quan sát:</strong> nếu các cột điều khiển độc lập đủ để phủ mọi hướng trạng thái qua thời gian, mô hình tuyến tính là điều khiển được. Nếu các hàng phép đo đủ phân biệt trạng thái, nó là quan sát được. Hạng thiếu chỉ ra hướng không thể tạo ra hoặc không thể suy ra từ các phép đo đã chọn.</div>'''
}

def matrix_demo(kind,title,intro):
    return f'''<section class="lab matrix-demo" data-matrix-demo="{kind}"><h2>{title}</h2><p>{intro}</p><div class="matrix-demo-layout"><canvas width="720" height="350" data-scene role="img" aria-label="Minh họa tương tác {title}"></canvas><div class="matrix-demo-panel"><div data-controls></div><div class="matrix-demo-result" data-result aria-live="polite"></div></div></div></section>'''

MATRIX_DEMOS = {
 (2,0): matrix_demo('products','Thử nhân hai vector','Kéo độ lớn và góc giữa hai mũi tên. Quan sát tích vô hướng là một số; tích có hướng là một vector chọc ra hoặc đi vào mặt phẳng.' )+matrix_demo('torque','Lực đặt ở đâu thì tạo mô-men nào?','Đổi vị trí đặt lực r theo trục x và lực nâng F theo trục z. Mũi tên mô-men xuất hiện theo trục y đúng quy tắc bàn tay phải.'),
 (2,1): matrix_demo('linear','Ma trận biến cả một mặt phẳng như thế nào?','Chuyển giữa xoay, xô nghiêng, phản xạ và ép phẳng. Nhìn ô vuông và hai trục cơ sở biến thành gì để hiểu định thức, hạng và nghịch đảo.')+matrix_demo('rotation','Ma trận xoay biến vector trong không gian','Giữ tọa độ vector trong hệ thân, rồi quay drone. Xem ba cột của R đổi như thế nào và tọa độ world của vector được tính ra sao.'),
 (4,1): matrix_demo('rotation','Thử đổi body → world bằng R','Thay yaw và vector thân để quan sát cùng một vector thân có tọa độ thế giới khác nhau khi drone quay.'),
 (10,2): matrix_demo('mixer','Bốn cột ma trận mixer tạo ra gì?','Thay riêng thrust từng rotor. Sơ đồ cho thấy motor nào tăng và bốn đầu ra T, roll, pitch, yaw thay đổi thế nào.')
}
